import React, { useStat } from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import './index.css';
import { HomePage, DatabasePage, GuidesPage, ItemsPage, NotamonPage, SignUpPage, LoginPage, NavBar, Footer } from './components';
import 'bootstrap/dist/css/bootstrap.min.css';

const App = () => {
  const [progress, setProgress] = useState(null);

  return(
    <BrowserRouter>
      <NavBar progress={progress} onProgressUpdate={setProgress} />
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/database" element={<DatabasePage onProgressUpdate={setProgress}/>} />
        <Route path="/guides" element={<GuidesPage />} />
        <Route path="/items" element={<ItemsPage />} />
        <Route path="/notamon/*" element={<NotamonPage />} />
        <Route path="/signup" element={<SignUpPage />} />
        <Route path="/login" element={<LoginPage />} />
      </Routes>
      <Footer />
    </BrowserRouter>
  );
}
